android.extraProguardRules:
# General Optimization and Deobfuscation Attributes
-keepattributes SourceFile,LineNumberTable
-keepattributes *Annotation*
-keepattributes Signature
-keepattributes InnerClasses,EnclosingMethod

# Suppress harmless build-time warnings for optional dependencies
-dontwarn javax.annotation.**
-dontwarn org.checkerframework.**
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn kotlin.reflect.**
-dontwarn sun.misc.Unsafe
-dontwarn io.sentry.**
-dontwarn io.invertase.googlemobileads.**

# React Native & Hermes JNI
-keep class com.facebook.hermes.unicode.** { *; }
-keep class com.facebook.jni.HybridData { *; }
-keep class com.facebook.jni.CppSystemErrorException { *; }
-keep @com.facebook.proguard.annotations.DoNotStrip class * { *; }
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keep class * extends com.facebook.react.bridge.JavaScriptModule { *; }
-keep class * extends com.facebook.react.bridge.NativeModule { *; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }

# Expo Modules Core & Kotlin Record Reflection (surgical for R8 Full Mode)
-keep class kotlin.Metadata { *; }
-keep class * extends expo.modules.kotlin.modules.Module { public <init>(...); }
-keep class * implements expo.modules.core.interfaces.Package { public <init>(...); }
-keep class * implements expo.modules.kotlin.records.Record { *; }
-keepclassmembers class * implements expo.modules.kotlin.records.Record { *; }
-keep @interface expo.modules.kotlin.records.Field
-keepclassmembers class * {
    @expo.modules.kotlin.records.Field *;
}
-keep class * implements expo.modules.kotlin.types.Enumerable { *; }
-keepclassmembers enum * implements expo.modules.kotlin.types.Enumerable { *; }
-keep class expo.modules.kotlin.allocators.** { *; }

# Google Mobile Ads / AdMob & UMP
-keep class io.invertase.googlemobileads.** { *; }
-keep class com.google.android.gms.ads.MobileAds { public static *; }
-keep class com.google.android.ump.UserMessagingPlatform { public static *; }
-keep class com.google.android.ump.ConsentInformation { *; }

# Google Play Integrity (expo-app-integrity)
-keep class com.google.android.play.core.integrity.IntegrityManager** { *; }
-keep class com.google.android.play.core.integrity.StandardIntegrityManager** { *; }
-keep class expo.modules.integrity.** { *; }

# Google Play Billing (expo-iap)
-keep class com.android.billingclient.api.BillingClient** { *; }
-keep class expo.modules.iap.** { *; }

# Health Connect & Nitro / MMKV JNI bridges
-keep class dev.matinzd.healthconnect.** { *; }
-keep class com.margelo.nitro.HybridObject { *; }
-keep class com.tencent.mmkv.MMKV { *; }
